head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > mergeCell]<br/>Body Cell 정보를 사용하여 Body 영역의 특정 Cell 을 병합합니다.",
    "validation" : [
        "mergeInfo.rowIndex(필수) 파라미터로 병합을 시작하려는 Body Cell 의 Row 인덱스를 설정합니다. (0부터, GridView 에 표시된 Row 기준)",
        "mergeInfo.colIndex(필수) 파라미터로 병합을 시작하려는 Body Cell 의 Column 인덱스를 설정합니다. (0부터, 숨겨진 Column 포함)",
        "mergeInfo.rowSpan(선택, 기본 1) 파라미터로 병합할 Body Cell 의 Row 수를 설정합니다.",
        "mergeInfo.colSpan(선택, 기본 1) 파라미터로 병합할 Body Cell 의 Column 수를 설정합니다.",
        "rowSpan, colSpan 파라미터를 모두 1 로 설정하면 해당 Cell 의 병합이 해제됩니다.",
        "병합되는 Cell 에는 시작 위치의 Cell 데이터가 복사되며 DataList 의 실제 데이터가 변경됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // par_ 기본값 설정 (selectbox 초기 선택 — 2x2 병합 데모 기준값)
    par_rowIndex.setValue("0");
    par_colIndex.setValue("1");
    par_rowSpan.setValue("2");
    par_colSpan.setValue("2");

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 데이터 — 모든 Cell 값이 서로 다름(R{행}C{컬럼}). 병합 시 흡수 Cell 에 시작 Cell 값이
//          복사되는지(@spec2), 병합 영역을 눈으로 확인 가능하게 한다.
scwin.MERGE_DATA = [
    { "col1": "R0C0", "col2": "R0C1", "col3": "R0C2", "col4": "R0C3" },
    { "col1": "R1C0", "col2": "R1C1", "col3": "R1C2", "col4": "R1C3" },
    { "col1": "R2C0", "col2": "R2C1", "col3": "R2C2", "col4": "R2C3" },
    { "col1": "R3C0", "col2": "R3C1", "col3": "R3C2", "col4": "R3C3" },
    { "col1": "R4C0", "col2": "R4C1", "col3": "R4C2", "col4": "R4C3" }
];



// comp 생성 : 단일 그리드 1개를 동적 생성한다.
//  ★ mergeCells 속성은 부여하지 않음(수동 병합 mergeCell 전용).
//     mergeCell 은 메소드 호출이므로 dynamicCreate 후 par_ 입력 기반으로 호출한다.
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="5행 4열 그리드. 모든 Cell 값이 서로 다름(R{행}C{컬럼}). mergeCell 로 시작 Cell(rowIndex,colIndex) 부터 rowSpan x colSpan 영역을 수동 병합 → 흡수 Cell 에 시작 Cell 값이 복사됨"', '', 'label1');

    // DataList 생성 후 검증용 데이터 적재
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON(scwin.MERGE_DATA, false);

    let cList = $c.gcm.createCList({ dataList: "data:" + dlt_bind.id });

    let grp_comp = document.querySelector('.tc_group_basic');
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" defaultCellHeight="38" id="" style="width:520px;height:230px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeCell sample"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column1" value="col0"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column2" value="col1"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column3" value="col2"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="column4" value="col3"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 공통 : 병합 시작(anchor) td 의 rowSpan/colSpan 과 표시값을 반환
//  - td id 형식 : target1_cell_{row}_{col}
scwin.getAnchorSpan = function (rowIndex, colIndex) {
    let td = document.querySelector("td[id*='target1_cell_" + rowIndex + "_" + colIndex + "']");
    if (!td) return null;
    return { rowSpan: td.rowSpan || 1, colSpan: td.colSpan || 1, text: (td.textContent || '').trim() };
}



// mergeCell 실행 : par_ 4개 값(rowIndex/colIndex/rowSpan/colSpan)을 읽어 호출한다.
//  - rowSpan/colSpan 은 선택(기본 1) → 입력값이 비어 있으면 mergeInfo 에서 생략하여 기본 1 로 동작하는지 확인.
scwin.btn_mergeCell_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let rowIndex = Number(par_rowIndex.getValue());
    let colIndex = Number(par_colIndex.getValue());
    let rowSpanStr = par_rowSpan.getValue();
    let colSpanStr = par_colSpan.getValue();

    // 필수 : rowIndex, colIndex
    let mergeInfo = { "rowIndex": rowIndex, "colIndex": colIndex };

    // 선택 : rowSpan / colSpan — 비어 있으면 생략(기본 1 동작 확인)
    let rowSpanOmit = (rowSpanStr === '' || rowSpanStr === null);
    let colSpanOmit = (colSpanStr === '' || colSpanStr === null);
    if (!rowSpanOmit) mergeInfo.rowSpan = Number(rowSpanStr);
    if (!colSpanOmit) mergeInfo.colSpan = Number(colSpanStr);

    target1.mergeCell(mergeInfo);

    // 병합 결과 : 시작 Cell(anchor) 의 rowSpan / colSpan / 표시값 (rowSpan/colSpan 생략 시 기본 1 동작 확인)
    let anchor = scwin.getAnchorSpan(rowIndex, colIndex);
    if (anchor) {
        bottom.setReturnValue("시작 Cell (" + rowIndex + "," + colIndex + ") rowSpan=" + anchor.rowSpan
            + " / colSpan=" + anchor.colSpan + " / 표시값='" + anchor.text + "'"
            + (rowSpanOmit ? " [rowSpan 생략 → 기본 1]" : "")
            + (colSpanOmit ? " [colSpan 생략 → 기본 1]" : ""));
    } else {
        bottom.setReturnValue("시작 Cell td 를 찾을 수 없습니다.");
    }
}



// 병합 해제 : par_rowIndex / par_colIndex 가 가리키는 시작 Cell 에 rowSpan=1, colSpan=1 로 mergeCell 호출
//  → @spec1 : 모두 1 로 설정하면 해당 Cell 의 병합이 해제됨
scwin.btn_unmerge_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let rowIndex = Number(par_rowIndex.getValue());
    let colIndex = Number(par_colIndex.getValue());

    target1.mergeCell({ "rowIndex": rowIndex, "colIndex": colIndex, "rowSpan": 1, "colSpan": 1 });

    let anchor = scwin.getAnchorSpan(rowIndex, colIndex);
    if (anchor) {
        let released = (anchor.rowSpan === 1 && anchor.colSpan === 1);
        bottom.setReturnValue("rowSpan=" + anchor.rowSpan + " / colSpan=" + anchor.colSpan + " → 병합 해제 : " + released);
    }
}



// 데이터 복사 확인 : @spec2 — 병합 후 흡수된 Cell 들의 DataList 실제 데이터가 시작 Cell 값으로 변경되는지 확인
//  - dlt_bind.getCellData(row, colId) 로 바인딩된 DataList 의 실제 데이터를 조회
//  - 표시값(grid 표시) 도 함께 비교
scwin.btn_checkCopy_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let rowIndex = Number(par_rowIndex.getValue());
    let colIndex = Number(par_colIndex.getValue());
    let rowSpan = Number(par_rowSpan.getValue() || 1);
    let colSpan = Number(par_colSpan.getValue() || 1);

    let colIds = ["col1", "col2", "col3", "col4"];

    // 시작 Cell 의 실제 DataList 데이터(기준값)
    let startData = dlt_bind.getCellData(rowIndex, colIds[colIndex]);

    // 흡수된 Cell 들의 DataList 데이터가 시작 Cell 값으로 복사되었는지 확인
    let allCopied = true;
    for (let r = rowIndex; r < rowIndex + rowSpan; r++) {
        for (let c = colIndex; c < colIndex + colSpan; c++) {
            if (r === rowIndex && c === colIndex) continue; // 시작 Cell 제외
            if (String(dlt_bind.getCellData(r, colIds[c])) !== String(startData)) allCopied = false;
        }
    }

    bottom.setReturnValue("시작 Cell DataList 값='" + startData + "' / 모든 흡수 Cell 이 시작값으로 변경됨 : " + allCopied);
}
